package dev.eugheist.tc4modern;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class CrabAudit {
 static final BlockPos BASE=new BlockPos(860,121,-90);static int ticks;static volatile String failed;static EldritchCrab rider,fighter;static InhabitedZombie zombie;static net.minecraft.world.entity.animal.Cow victim,prey;static float before;static int crabsBefore;static void check(boolean ok,String msg){if(!ok)failed=msg;System.out.println("TC4_CRAB "+(ok?"PASS ":"FAIL ")+msg);if(!ok)throw new IllegalStateException(msg);}
 static EldritchCrab crab(net.minecraft.server.level.ServerLevel l,int x,int z,boolean helm){var c=CrabContent.CRAB.get().create(l);c.moveTo(BASE.getX()+x+.5,BASE.getY(),BASE.getZ()+z+.5,0,0);c.setHelm(helm);l.addFreshEntity(c);return c;}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("tc4modern.crabAuditOnly"))return;var mc=Minecraft.getInstance();if(mc.player==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();
 if(ticks==40)server.execute(()->{var p=server.getPlayerList().getPlayer(id);var l=server.overworld();p.teleportTo(l,BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-7,0,7);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.getAbilities().flying=true;p.onUpdateAbilities();p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.NIGHT_VISION,1200,0,false,false));l.setDayTime(18000);l.getEntitiesOfClass(Entity.class,new AABB(BASE).inflate(40),e->!(e instanceof net.minecraft.world.entity.player.Player)).forEach(Entity::discard);for(int x=-16;x<=16;x++)for(int z=-3;z<=25;z++)for(int y=-1;y<10;y++)l.setBlock(BASE.offset(x,y,z),(y==-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),3);
 var helmet=crab(l,-5,3,true);helmet.setNoAi(true);check(helmet.getMaxHealth()==20&&helmet.getArmorValue()==5&&Math.abs(helmet.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)-.275)<.0001,"helmet gives original armor, health and speed");var bare=crab(l,-2,3,false);bare.setNoAi(true);check(bare.getArmorValue()==0&&bare.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)==.3,"bare crab is faster and unarmored");check(!bare.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.POISON,100)),"crab refuses poison");check(bare.getType().is(net.minecraft.tags.EntityTypeTags.ARTHROPOD),"crab has arthropod damage tag");
 var shell=crab(l,10,12,true);shell.setNoAi(true);shell.hurt(shell.damageSources().genericKill(),11);check(!shell.hasHelm()&&shell.getArmorValue()==0&&shell.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED)==.3,"half-health hit removes shell and changes armor/speed");check(l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,shell.getBoundingBox().inflate(2)).stream().anyMatch(e->e.getItem().is(PechTrades.mod("cultist_plate_chestplate").getItem())),"lost shell drops cultist plate chestpiece");shell.discard();var tag=new net.minecraft.nbt.CompoundTag();helmet.saveWithoutId(tag);var copy=CrabContent.CRAB.get().create(l);copy.load(tag);check(copy.hasHelm()&&copy.getArmorValue()==5,"shell flag and armor persist");
 zombie=CrabContent.ZOMBIE.get().create(l);zombie.moveTo(BASE.getX()+3,BASE.getY(),BASE.getZ()+3,180,0);zombie.finalizeSpawn(l,l.getCurrentDifficultyAt(zombie.blockPosition()),MobSpawnType.SPAWN_EGG,null);zombie.setNoAi(true);l.addFreshEntity(zombie);check(zombie.getMaxHealth()==30&&zombie.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE)==5&&zombie.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.SPAWN_REINFORCEMENTS_CHANCE)==0,"inhabited zombie original combat attributes");check(zombie.getItemBySlot(EquipmentSlot.HEAD).is(PechTrades.mod("cultist_plate_helmet").getItem()),"inhabited zombie spawns wearing cultist helmet");
 rider=crab(l,-5,10,false);victim=EntityType.COW.create(l);victim.moveTo(rider.getX(),BASE.getY(),rider.getZ(),0,0);victim.setNoAi(true);l.addFreshEntity(victim);rider.setTarget(victim);rider.setPos(victim.getX(),victim.getY()+1.4,victim.getZ());rider.setOnGround(false);before=victim.getHealth();fighter=crab(l,3,12,true);prey=EntityType.COW.create(l);prey.moveTo(fighter.getX()+2,BASE.getY(),fighter.getZ(),0,0);prey.setNoAi(true);l.addFreshEntity(prey);fighter.setTarget(prey);
 });
 if(ticks==70)server.execute(()->check(rider.isPassenger()&&rider.getVehicle()==victim,"airborne bare crab jumps onto target"));
 if(ticks==100)LiquidDeathAudit.shot(mc,"crab-family.png");
 if(ticks==130)server.execute(()->{check(victim.getHealth()<before||!victim.isAlive(),"mounted crab naturally damages its host");check(prey.getHealth()<prey.getMaxHealth()||!prey.isAlive(),"armored crab naturally attacks target");fighter.setNoAi(true);rider.setNoAi(true);var l=server.overworld();crabsBefore=l.getEntitiesOfClass(EldritchCrab.class,new AABB(BASE).inflate(40)).size();zombie.lastHurtByPlayerTime=100;zombie.hurt(zombie.damageSources().genericKill(),1000);});
 if(ticks==140)server.execute(()->{var l=server.overworld();var near=l.getEntitiesOfClass(EldritchCrab.class,new AABB(BASE).inflate(40));check(zombie.isRemoved()&&near.size()==crabsBefore+1,"inhabited zombie death releases exactly one crab");check(near.stream().anyMatch(c->c.hasHelm()&&c.distanceToSqr(zombie)<9),"released crab wears shell at corpse position");check(l.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,zombie.getBoundingBox().inflate(2)).stream().noneMatch(e->e.getItem().is(net.minecraft.world.item.Items.ROTTEN_FLESH)||e.getItem().is(PechTrades.mod("cultist_plate_helmet").getItem())),"inhabited death avoids vanilla flesh and equipment loot");var p=server.getPlayerList().getPlayer(id);p.getInventory().clearContent();int slot=0;for(String name:java.util.List.of("eldritch_crab","inhabited_zombie")){var egg=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(AlchemyContent.id(name+"_spawn_egg"));p.getInventory().setItem(slot++,new net.minecraft.world.item.ItemStack(egg));}p.containerMenu.broadcastChanges();var drop=new net.minecraft.world.entity.item.ItemEntity(l,p.getX(),p.getY()+.5,p.getZ()+2,p.getMainHandItem().copy());drop.setNoGravity(true);drop.setNeverPickUp();drop.setDeltaMovement(Vec3.ZERO);l.addFreshEntity(drop);});
 if(ticks==160)LiquidDeathAudit.shot(mc,"crab-eggs-hand.png");if(ticks==170)mc.setScreen(new net.minecraft.client.gui.screens.inventory.InventoryScreen(mc.player));if(ticks==180){LiquidDeathAudit.shot(mc,"crab-eggs-inventory.png");mc.setScreen(null);}if(ticks==190)mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_FRONT);if(ticks==200)LiquidDeathAudit.shot(mc,"crab-eggs-third.png");if(ticks==210){mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);check(CrabClient.crabs>0&&CrabClient.zombies>0,"crab and inhabited zombie renderers used");System.out.println(failed==null?"TC4_CRAB ALL PASS":"TC4_CRAB FAILED "+failed);mc.stop();}
 }
}
